create table if not exists public.business_subscriptions (id uuid primary key default gen_random_uuid(),business_id uuid not null,tier_code text not null,billing_cycle text not null check (billing_cycle in ('MONTHLY','ANNUAL','TRIAL')),status text not null check (status in ('TRIALING','PENDING_PAYMENT','ACTIVE','PAST_DUE','CANCELLED','EXPIRED')),sector text,starts_at timestamptz not null,ends_at timestamptz,provider text,provider_reference text,source_payment_intent_id uuid,idempotency_key text,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create unique index if not exists uq_business_subscriptions_idempotency on public.business_subscriptions(idempotency_key) where idempotency_key is not null; create index if not exists ix_business_subscriptions_business_status on public.business_subscriptions(business_id,status); alter table public.business_subscriptions enable row level security; drop policy if exists business_subscriptions_owner_select on public.business_subscriptions; create policy business_subscriptions_owner_select on public.business_subscriptions for select to authenticated using (exists (select 1 from public.user_memberships m where m.user_id=auth.uid() and m.status='ACTIVE' and m.business_id=business_subscriptions.business_id)); create or replace function public.start_business_trial_backend(p_business_id uuid,p_tier_code text,p_sector text,p_trial_days integer,p_idempotency_key text,p_actor_user_id uuid) returns public.business_subscriptions language plpgsql security definer set search_path='' as $$ declare v public.business_subscriptions; begin if p_actor_user_id is null then raise exception 'unauthorized'; end if; if not exists (select 1 from public.user_memberships m where m.user_id=p_actor_user_id and m.business_id=p_business_id and m.status='ACTIVE') then raise exception 'forbidden'; end if; if p_trial_days < 1 or p_trial_days > 90 then raise exception 'invalid_trial_days'; end if; select * into v from public.business_subscriptions where idempotency_key=p_idempotency_key limit 1; if v.id is not null then return v; end if; insert into public.business_subscriptions(business_id,tier_code,billing_cycle,status,sector,starts_at,ends_at,idempotency_key,created_by) values(p_business_id,p_tier_code,'TRIAL','TRIALING',p_sector,now(),now()+make_interval(days=>p_trial_days),p_idempotency_key,p_actor_user_id) returning * into v; return v; end; $$; revoke all on function public.start_business_trial_backend(uuid,text,text,integer,text,uuid) from public,anon,authenticated; grant execute on function public.start_business_trial_backend(uuid,text,text,integer,text,uuid) to service_role;
